import socket, time
H="ws345jh11k.b8vr8jb5eb.tsdb.cloud.timescale.com"
for host,port in [(H,31089),(H,5432),(H,443),("github.com",22),("smtp.gmail.com",587),("github.com",443)]:
    t=time.time()
    try:
        socket.create_connection((host,port),timeout=5).close(); r="OPEN"
